<template>
 <section class="music-playlist" :class="{'read-only':!editable}" :aria-label="$t('Playlist multitrack')">
  <div class="playlist-ruler"><span>{{ $t('Canales SPC700') }}</span><MusicTimeRuler :width="width" :start="start" :span="span" :cursor="cursor" @seek="$emit('seek',$event)" @scrub-start="$emit('scrub-start')" @scrub-end="$emit('scrub-end')" /></div>
  <div class="playlist-tracks" @wheel.prevent="wheel">
   <div v-for="t in tracks" :key="t.channel" class="music-track" :class="{selected:t.channel===channel,empty:!t.regions.length,'solo-muted':solo!==null&&solo!==undefined&&solo!==t.channel}" :style="{'--track-color':colors[t.channel%colors.length]}">
    <div class="track-heading"><button class="track-select" @click="$emit('track',t.channel)"><span class="track-number">{{String(t.channel+1).padStart(2,'0')}}</span><span><strong>{{ $t('Canal') }} {{t.channel+1}}</strong><small>{{ $t('Instrumento') }} {{t.instrument}} {{t.loop?'· ↻':''}}</small></span></button><button class="track-solo" :class="{active:solo===t.channel}" :aria-pressed="solo===t.channel" :disabled="!t.regions.length" :aria-label="$t('Escuchar solo este canal')+' '+(t.channel+1)" :title="$t(solo===t.channel?'Escuchar todos los canales':'Escuchar solo este canal')" @click="$emit('solo',t.channel)">{{ $t('Solo') }}</button></div>
    <div class="track-lane" :style="{width:width+'px',backgroundSize:(192/span*width)+'px 100%',backgroundPosition:(-start/span*width)+'px 0'}">
     <button v-for="r in visible(t.regions)" :key="r.id" class="pattern-block" :class="{selected:selected.includes(r.id)}" :style="blockStyle(r)" :aria-label="`${$t('Región')} ${r.start/192+1} · ${$t('Canal')} ${t.channel+1}`" :title="$t(editable?'Doble clic para abrir; arrastra para mover la región.':'Doble clic para ver las notas.')" @pointerdown="begin($event,r,'move')" @pointermove="move" @pointerup="finish" @pointercancel="cancel" @dblclick="$emit('open',r)" @keydown.enter.prevent="$emit('open',r)">
      <span class="pattern-name">{{ $t('Región') }} {{r.start/192+1}} · {{r.notes.length}} ♪</span><MusicNotePreview :notes="r.notes.map(n=>n.note)" :start="r.start" :span="r.end-r.start" />
      <span v-if="editable" class="region-resize" @pointerdown.stop="begin($event,r,'resize')" @pointermove.stop="move" @pointerup.stop="finish" @pointercancel.stop="cancel" :title="$t('Cambiar duración de la región')" />
     </button>
     <MusicTimeRuler marker-only :width="width" :start="start" :span="span" :cursor="cursor" @seek="$emit('seek',$event)" @scrub-start="$emit('scrub-start')" @scrub-end="$emit('scrub-end')" />
    </div>
   </div>
  </div>
 </section>
</template>
<script>
import MusicTimeRuler from './MusicTimeRuler.vue';import MusicNotePreview from './MusicNotePreview.vue';import {snapTick} from '../editor/timeline.mjs';
export default {components:{MusicTimeRuler,MusicNotePreview},props:{tracks:Array,colors:Array,start:Number,span:Number,width:Number,cursor:Number,selected:Array,channel:Number,editable:Boolean,snap:Number,solo:{type:Number,default:null}},emits:['solo','select','open','track','edit','seek','scrub-start','scrub-end','pan','zoom'],data(){return {drag:null};},methods:{
 visible(regions){return regions.filter(r=>r.end>=this.start&&r.start<=this.start+this.span);},
 blockStyle(r){const delta=this.drag?.region.id===r.id?this.drag.delta:0,resize=this.drag?.region.id===r.id&&this.drag.kind==='resize';return {left:(r.start-this.start+(resize?0:delta))/this.span*this.width+'px',width:Math.max(18,(r.end-r.start+(resize?delta:0))/this.span*this.width)+'px'};},
 begin(e,r,kind){if(e.button!==0)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);this.$emit('select',{region:r,add:e.shiftKey||e.ctrlKey||e.metaKey});if(!this.editable)return;this.drag={x:e.clientX,region:r,kind,delta:0};},
 move(e){if(!this.drag)return;const delta=Math.round((e.clientX-this.drag.x)/this.width*this.span/this.snap)*this.snap;this.drag.delta=this.drag.kind==='move'?Math.max(-this.drag.region.start,delta):Math.max(this.snap-(this.drag.region.end-this.drag.region.start),delta);},
 finish(){const d=this.drag;this.drag=null;if(!d||!d.delta)return;this.$emit('edit',d.kind==='move'?{type:'move-regions',region:d.region,tickDelta:d.delta}:{type:'stretch',refs:d.region.notes.map(n=>({channel:n.channel,index:n.index})),start:d.region.start,factor:(d.region.end-d.region.start+d.delta)/(d.region.end-d.region.start)});},cancel(){this.drag=null;},
 wheel(e){if(e.ctrlKey||e.metaKey)this.$emit('zoom',Math.exp(Math.max(-1,Math.min(1,e.deltaY*.002))));else if(e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY))this.$emit('pan',(e.deltaX||e.deltaY)/this.width*this.span);else this.$el.querySelector('.playlist-tracks').scrollTop+=e.deltaY;}
}};
</script>
<style scoped>
.music-playlist{border-bottom:1px solid #354153}.playlist-ruler{display:flex;background:#1d2836}.playlist-ruler>span{width:176px;flex-shrink:0;box-sizing:border-box;padding:9px 12px;font-size:10px;color:#a6bad2;text-transform:uppercase;letter-spacing:.06em}.playlist-tracks{max-height:300px;overflow:auto;overscroll-behavior:contain}.music-track{display:flex;min-width:0;border-bottom:1px solid #2b3849;height:76px}.track-heading{box-sizing:border-box;display:flex;gap:9px;align-items:center;width:176px;flex-shrink:0;text-align:left;border:0;border-left:3px solid var(--track-color);border-radius:0;background:#202c3c;color:#deebf8;padding:10px;cursor:pointer}.track-select{display:flex;align-items:center;gap:8px;flex:1;min-width:0;padding:0;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer}.track-select>span:last-child{min-width:0}.track-solo{flex-shrink:0;padding:5px 4px;border:1px solid #52677f;border-radius:4px;background:#172536;color:#bfd0e3;font-size:10px;cursor:pointer}.track-solo.active{background:#c49b45;color:#17212b;border-color:#f2cb7e}.track-solo:disabled{opacity:.35;cursor:default}.solo-muted .track-lane{opacity:.4}.track-solo:focus-visible,.track-select:focus-visible{outline:2px solid white;outline-offset:2px}.track-heading strong{display:block;font-size:12px}.track-heading small{display:block;color:#9caec6;font-size:10px;margin-top:6px}.track-number{font:18px monospace;color:var(--track-color)}.selected>.track-heading{background:#2a3b51}.track-lane{position:relative;overflow:hidden;flex-shrink:0;background-image:linear-gradient(90deg,#7388a422 1px,transparent 1px);background-color:#121c28}.empty .track-lane{background-color:#16202b}.pattern-block{position:absolute;top:7px;height:61px;padding:20px 0 0;overflow:hidden;color:var(--track-color);border:1px solid var(--track-color);border-radius:4px;background:color-mix(in srgb,var(--track-color) 15%,#172330);cursor:grab;touch-action:none;box-sizing:border-box}.read-only .pattern-block{cursor:pointer}.pattern-block.selected{box-shadow:inset 0 0 0 2px var(--track-color);background:color-mix(in srgb,var(--track-color) 30%,#172330)}.pattern-name{position:absolute;top:4px;left:7px;white-space:nowrap;font-size:10px;color:#ecf4ff}.region-resize{position:absolute;right:0;top:0;bottom:0;width:8px;cursor:ew-resize;background:#ffffff20}.edit-cursor{position:absolute;top:0;bottom:0;width:1px;background:#f2c065;pointer-events:none;z-index:2}.track-heading:focus-visible,.pattern-block:focus-visible{outline:2px solid white;outline-offset:-2px}
</style>
